def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged = [list(sorted_intervals[0])]

    for i in range(1, len(sorted_intervals)):
        curr_start, curr_end = sorted_intervals[i]
        last = merged[-1]
        if curr_start <= last[1]:
            last[1] = max(last[1], curr_end)
        else:
            merged.append([curr_start, curr_end])

    return merged

import heapq


def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in edges:
        if dst not in adj[src]:
            adj[src].add(dst)
            in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    if not items:
        return []
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if current_sum + weight > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (no '=' found): {line!r}")

        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()

        if not key_pattern.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2:
            if (value[0] == '"' and value[-1] == '"') or (
                value[0] == "'" and value[-1] == "'"
            ):
                value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    result = []
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    break
                result.append(data)
            data_lines = []
        elif line.startswith(':'):
            pass
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            data_lines.append(value)
        else:
            pass

    return result

import math


def retry_delay(attempt, base, cap):
    """Return min(cap, base * 2**attempt) as a float.

    Avoids constructing 2**attempt for huge attempt values.
    """
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if base < 0:
        raise ValueError("base must be nonnegative")
    if cap < 0:
        raise ValueError("cap must be nonnegative")
    if not math.isfinite(base) or not math.isfinite(cap):
        raise ValueError("base and cap must be finite")

    # Early exits for zero arguments
    if base == 0 or cap == 0:
        return 0.0

    # If base >= cap, then base * 2^attempt >= base >= cap for any attempt >= 0
    if base >= cap:
        return float(cap)

    # Now: 0 < base < cap
    # Determine whether base * 2^attempt >= cap without computing 2^attempt.
    # base * 2^attempt >= cap  <=>  attempt >= log2(cap / base)
    threshold = math.log2(cap / base)

    if attempt >= threshold:
        return float(cap)

    # Here attempt < log2(cap/base), so the result is strictly less than cap
    # (and thus finite).  For finite floats, log2(cap/base) <= ~2098, so
    # math.ldexp will not overflow.  This avoids ever building 2**attempt
    # as a Python integer.
    result = math.ldexp(float(base), int(attempt))
    return float(min(cap, result))

def fifo_admit(active, queued, budget, slots):
    for req in queued:
        if req > budget:
            raise ValueError(f"queued reservation {req} exceeds budget {budget}")

    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    i = 0
    for req in queued:
        if remaining_slots > 0 and req <= remaining_budget:
            admitted.append(req)
            remaining_budget -= req
            remaining_slots -= 1
            i += 1
        else:
            break

    remaining = list(queued[i:])
    return (admitted, remaining)
